function longestCleanStreak(log) {
    let best = 0;
    for (let start = 0; start < log.length; start++) {
        const seen = new Set();
        for (let end = start; end < log.length; end++) {
            if (seen.has(log[end]))
                break;
            seen.add(log[end]);
            best = Math.max(best, end - start + 1);
        }
    }
    return best;
}

function longestCleanStreak(log) {
    const lastSeen = new Map();
    let best = 0;
    let start = 0;
    for (let i = 0; i < log.length; i++) {
        const previous = lastSeen.get(log[i]);
        if (previous !== undefined && previous >= start)
            start = previous + 1;
        lastSeen.set(log[i], i);
        best = Math.max(best, i - start + 1);
    }
    return best;
}
